import{interestRoles,preparationChoices,roleLabel,preparationLabel}from './study-intent.js?v=0.17.0';
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function studyIntentBadge(state,pathId){const role=state?.answers?.[pathId]?.role;return role?`<p class="intent-badge"><strong>Your current intention:</strong> ${h(roleLabel(role))}</p>`:'';}
export function studyIntentQuestions(p,state){const a=state?.answers?.[p.id]||{},select=(field,options)=>`<select id="intent-${field}-${p.id}" data-intent-field="${field}" data-intent-path="${p.id}"><option value="">Not answered yet</option>${options.map(([key,label])=>`<option value="${key}" ${a[field]===key?'selected':''}>${h(label)}</option>`).join('')}</select>`;return`<section class="panel study-intent" aria-label="How this interest could fit into college"><h2>How could this interest fit into college?</h2><p>Two optional planning questions for <strong>${h(p.title)}</strong>. Enjoying something does not mean it needs to become your major or job.</p><div class="intent-fields"><label for="intent-role-${p.id}"><span class="field-label">Would you like to study this, keep it as an activity, or try it first?</span>${select('role',interestRoles)}</label><label for="intent-route-${p.id}"><span class="field-label">Which education route would you like to compare first?</span>${select('route',preparationChoices)}</label></div><p class="subtle">These answers label your exploration plan. They do not change your interest scores, subject clues, suggestions, shortlist or saved programs. “Unsure” is a useful answer; you can revise it anytime.</p>${a.role==='hobby'?'<p class="note">Keep room for this interest through campus groups, projects or community activities. Your existing saved possibilities stay yours to review.</p>':''}</section>`;}
export function studyIntentPlan(paths,state){const rows=paths.filter(p=>Object.keys(state?.answers?.[p.id]||{}).length);return rows.length?`<section class="panel"><h2>Interests I want to keep in my college life</h2><p>A subject can belong in your plan without becoming a major or profession.</p>${rows.map(p=>{const a=state.answers[p.id];return`<article class="intent-plan-item"><h3>${h(p.title)}</h3><p>${h(roleLabel(a.role))} · ${h(preparationLabel(a.route))}</p><p>${a.role==='hobby'?'Look for an optional club, elective or community activity; try it without treating it as career preparation.':h(p.activity)}</p><a class="text-link" href="#/path/${p.id}">Review my intention & routes ↗</a></article>`;}).join('')}</section>`:'';}
